import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().toInt()
    val dp = Array(n + 1) { LongArray(n + 1) }
    for (i in 1..n) {
        for (j in 1..n) {
            dp[i][j] = Long.MAX_VALUE / 2
        }
    }
    for (i in 1..n) {
        dp[i][i] = 0
    }
    for (length in 2..n) {
        for (i in 1..(n - length + 1)) {
            val j = i + length - 1
            if (length == 2) {
                dp[i][j] = 0
            } else {
                for (k in (i + 1)..(j - 1)) {
                    val cost = dp[i][k] + dp[k][j] + (i.toLong() * k * j)
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost
                    }
                }
            }
        }
    }
    println(dp[1][n])
}
