    if (n == 3) {
        println(6)
        return
    }
    val dp = Array(n + 1) { LongArray(n + 1) }
    for (i in 1..n) {
        for (j in 1..n) {
            dp[i][j] = 0L
        }
    }
    for (len in 3..n) {
        for (i in 1..(n - len + 1)) {
            val j = i + len - 1
            dp[i][j] = Long.MAX_VALUE
            for (k in (i + 1)..(j - 1)) {
                val cost = i.toLong() * k * j
                val left = if (k - i >= 2) dp[i][k] else 0L
                val right = if (j - k >= 2) dp[k][j] else 0L
                val total = left + right + cost
                if (total < dp[i][j]) {
                    dp[i][j] = total
                }
            }
        }
    }
    println(dp[1][n])
}
