    for (i in 0 until n) {
        for (j in 0 until n) {
            dp[i][j] = Long.MAX_VALUE / 2
        }
    }
    for (i in 0 until n - 1) {
        dp[i][i + 1] = 0L
    }
    for len in 2..n - 1 {
        for i in 0..n - 1 - len {
            val j = i + len
            for (k in i + 1 until j) {
                val cost = (i + 1).toLong() * (k + 1).toLong() * (j + 1).toLong()
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + cost)
            }
        }
    }
    println(dp[0][n - 1])
}
